import type { System } from "../../Engine/System";
import type { World } from "../../Engine/World";
import type { GridMap } from "../Data/GridMap";
import { HallEvents } from "../HallEvents";
import   {GridCoord, localToGrid} from "../Config/GridConfig";
import { BuildingEntity } from "../Entity/BuildingEntity";

export class HallClickSystem implements System  {

    private _world: World = null!;
    private _gridMap: GridMap;



    constructor(gridMap: GridMap) {
        this._gridMap = gridMap;
    }

    onStart(world: World): void {
        this._world = world;
        world.bus.on(HallEvents.INPUT_CLICK, this._onClick, this);

    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.INPUT_CLICK, this._onClick, this);

    }


    
    onTick(world: World, dt: number): void {
        
    }



    // ===== 核心：一次点击的分派 =====
    private _onClick(localX: number, localY: number): void {
        const g: GridCoord | null = localToGrid(localX, localY);
        if (!g) return;                       // 点到地图外面了

        const building: BuildingEntity | null = this._gridMap.getAt(g.gridX, g.gridY);

        if (building) {                       // 有建筑 → 收金（现在还没建筑可点，但别删）
            
            return;
        }



  
    }
}


